commands:
cd /workspace && python3 - <<'PYEOF'
script = r'''#!/usr/bin/env bash
# Sums replica counts of APPROVED services from replicas.csv -> out/result.txt
set -euo pipefail
CSV="${1:-./replicas.csv}"
OUT="${2:-./out/result.txt}"
if [[ ! -f "$CSV" ]]; then echo "ERROR: input CSV not found at: $CSV" >&2; exit 1; fi
mkdir -p "$(dirname "$OUT")"
awk -F',' '
NR==1 {
  for (i=1;i<=NF;i++) { h=tolower($i); gsub(/[^a-z]/,"",h)
    if (h ~ /status|approval|state/) statuscol=i
    if (h ~ /replica/)              repcol=i }
  if (!statuscol || !repcol) { print "ERROR: cannot find status/replica columns. Header: " $0 > "/dev/stderr"; exit 2 }
  next
}
{
  if ($0 ~ /^[[:space:]]*$/) next
  v=tolower($statuscol); gsub(/[^a-z]/,"",v)
  if (v=="approved") { n=$repcol; gsub(/[^0-9]/,"",n); total+=n+0; cnt++ }
}
END { printf "%d\n", total }
' "$CSV" | tee "$OUT"
echo "Wrote total to $OUT" >&2
'''
open("out/sum_replicas.sh","w").write(script)
print("written")
PYEOF
chmod +x out/sum_replicas.sh && echo "===" && cat out
